-- Are you planning to inject? Yes
-- HarmonyGames task injection — Julia Lawson · ZM3D beta live-ops + push calendar (synth-cut, Oct 1 2025).
-- Grounding, scenario notes and self-validation live in Working_Files/01_Grounding_Dossier.md, not here.
-- Literal values only (no NOW(), random() or generated UUIDs); parents before children;
-- every statement valid against Task_Authoring/references/universe_schema_live.json.
-- Re-apply this exact SQL before every agent run (Database tab -> Query -> Run Query).

-- ========================================================================
-- Slack asks/replies · Gmail (Brian handoff/slip) · GCal (Oct 8 release) · Drive (brief/deck/calendar/folder)
-- ========================================================================
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json) VALUES ('bca784379e7dbca9e64e79a64dfefbba', '1759263617.418209', 'D05SD5QLG94', 'message', 'EMPLOYEE_0008_SLACK_ID', 'Julia, I need the live-ops and push calendar for the beta buy we start Mon Oct 6 through Sun Nov 2. Every beat players can see in those weeks: which windows it runs in, if anything is held and until when, the push that goes with it, what still has to land before it runs and who owns that. Put it in the calendar sheet in your ZM Live Ops folder and link it on the calendar ticket. Then send me your recommendation back here, with the trade-offs, on what we run and what we hold in those weeks. The working rules for the calendar are in my brief, shared with you. This goes into the pivot call, so I need your call, not a list of what we have.', NULL, '1759263617.418209', 1, 1, '1759263878.305129', false, NULL, '[]', '[]', '[]', '2025-09-30T20:20:17.418209Z', '{}');

INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json) VALUES ('890dc27f56e8501bd7590ffdfc231057', '1759263878.305129', 'D05SD5QLG94', 'message', 'EMPLOYEE_0008_SLACK_ID', 'Two things the brief does not spell out. Pushes: plan the PNs Beta tab as it stands, one line per row, local notifications included. Leave off the four rows for things that are not in the beta: Hourly Coins, Nathan''s Treasure Hunt, Streak Fever and Axe Arena, just those four. Copy that does not name the game at all is fine to go out, the naming rule is only about wrong names. And keep Zombie Lane off the calendar, it is a permanent track with no window or reset to plan.', 'bca784379e7dbca9e64e79a64dfefbba', '1759263617.418209', 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-30T20:24:38.305129Z', '{}');

INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json) VALUES ('933cee9f6464a80e4b1f05259b595b20', '1758213623.552919', 'C08R8CHB0QL', 'message', 'EMPLOYEE_0016_SLACK_ID', 'Halloween one-off: approved from my side for one of the beta weeks. It can take a recurring slot that week, one themed prop set only, no new mechanics, and I sign the object off if it lands before the cut.', '9025d428af1f551a20e303c3acbc545b', '1758121809.236839', 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-18T16:40:23.552919Z', '{}');

INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json) VALUES ('669d15f685f158633e56302160957f1e', '1759270241.638119', 'D05GU6L0XFH', 'message', 'EMPLOYEE_0016_SLACK_ID', 'Coming back on the themed prop set I okayed in Martin''s thread: pulling my ok. Take it off the beta calendar, we are not spending art time on a theme we may not ship at all. Sorry for the flip, my later word on this one is the one that counts.', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-30T22:10:41.638119Z', '{}');

INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json) VALUES ('b5f2955c2e154efc6835946ecfe1758e', '1759265412.481909', 'C0880U9751A', 'message', 'EMPLOYEE_0012_SLACK_ID', 'Re-tested the weekly leaderboard on the current prod build: it still does not start a new week. I killed the app and reopened it twice, played a few levels, and my week is still last week one. Same on the second device.', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-09-30T20:50:12.481909Z', '{}');

