INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json) VALUES ('78aa8ed77c0bd7b8a3fad227b22bc3fb', '1759160203.696979', 'C093LEZGF6J', 'message', 'SLACK_BOT_0004_SLACK_ID', '', '4b7c41278397b56b36e9b2f8a820c454', '1758917788.864169', 0, 0, NULL, false, NULL, '[]', '[]', '[{"color":"24292f","fallback":"[harmonygames-Games/match3d] Comment on #468","footer":"<https://github.com/harmonygames-Games/match3d|harmonygames-Games/match3d>","footer_icon":"https://slack.github.com/static/img/favicon-neutral.png","id":1,"mrkdwn_in":["text"],"pretext":"<https://github.com/harmonygames-Games/match3d/pull/468#discussion_r2388843617|Comment> on pull request by <https://github.com/arthur.blake|arthur.blake>","text":"The Collect &amp; Win vials that spawn in the levels are still the first-pass models. The final vial models are missing, Claire has those on her list.","title":"<https://github.com/harmonygames-Games/match3d/pull/468|#468 Collect And Win>","ts":1759160201}]', '2025-09-29T15:36:43.696979Z', '{}');

UPDATE slack.slack_messages SET reply_count = 42, latest_reply = '1759162433.383449', attachments_json = '[{"actions":[{"id":"1","name":"SVC_0999_NAME","style":"","text":"Comment","type":"button","value":"{&amp;amp;quot;selectedOrg&amp;amp;quot;:&amp;amp;quot;harmonygames-Games&amp;amp;quot;,&amp;amp;quot;selectedOrgId&amp;amp;quot;:128738820,&amp;amp;quot;selectedRepo&amp;amp;quot;:&amp;amp;quot;match3d&amp;amp;quot;,&amp;amp;quot;selectedRepoId&amp;amp;quot;:913994143,&amp;amp;quot;number&amp;amp;quot;:468,&amp;amp;quot;htmlUrl&amp;amp;quot;:&amp;amp;quot;https://github.com/harmonygames-Games/match3d/pull/468&amp;amp;quot;,&amp;amp;quot;title&amp;amp;quot;:&amp;amp;quot;Collect And Win&amp;amp;quot;}"}],"callback_id":"pr-opened-interaction","color":"6f42c1","fallback":"[harmonygames-Games/match3d] Pull request opened by owen.baker","fields":[{"short":true,"title":"Reviewers","value":"<https://github.com/apps/coderabbitai|@coderabbitai[bot]>, <@EMPLOYEE_0025_SLACK_ID>"},{"short":true,"title":"Comments","value":"1"}],"footer":"<https://github.com/harmonygames-Games/match3d|harmonygames-Games/match3d>","footer_icon":"https://slack.github.com/static/img/favicon-neutral.png","id":1,"mrkdwn_in":["text"],"pretext":"Pull request opened by <https://github.com/owen.baker|owen.baker>","text":"## Summary by coderabbit\n\n• *New Features*  \n   • Added \"Collect &amp; Win\" live event: collect tokens in levels, track progress, claim stage rewards and a grand prize; main screen, progress widget, info panel, stage/prize items, and level-end token display.\n• *Improvements*  \n   • Tokens spawn in unlocked levels, persist on level win, can be saved/claimed; new VFX/animations and reward-screen queuing.\n• *Developer Tools*  \n   • Debug panel options to add tokens and reset event data; new backend requests to support the flow.\n• *Chores*  \n   • Added sprites, prefabs, materials and asset metadata for the event.","title":"<https://github.com/harmonygames-Games/match3d/pull/468|#468 Collect And Win>","ts":1758917785}]' WHERE id = '4b7c41278397b56b36e9b2f8a820c454';

