INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at, sequence) VALUES ('cmt_zom429_1', 'ZOM-429', 'usr_cd7849ec043ab3da', NULL, 'Checked the weekly rollover - if a player force-closes and reopens, they land in the new week fine, so not blocking. Leaving as-is for now.', false, '2025-09-16T18:12:04Z', '2025-09-16T18:12:04Z', 1);

INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at, sequence) VALUES ('cmt_zom556_1', 'ZOM-556', 'usr_65c76e0b87aa7e9b', NULL, 'Claimed the daily gift on the submission build after skipping a day, it paid out and moved to the next day. So the lower day row still carries on instead of going back to day 1, but claiming works and nothing is lost.', false, '2025-09-24T15:20:38Z', '2025-09-24T15:20:38Z', 1);
UPDATE linear.linear_issues SET updated_at = '2025-09-24T15:20:38Z' WHERE id = 'ZOM-556';

INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at, sequence) VALUES ('cmt_zom565_1', 'ZOM-565', 'usr_c77c50cc15c5342d', NULL, 'Calvin, I pushed a small change to the endless screen prefab on my branch (Marcus/EndlessMode_Vfx). The new bar is still hidden in there for you to hook up, and the glow still shows on every box until it is tied to the Claim state. This is the P1/P2 endless polish from the list Brian gave me, the screen already works without it, so it is not needed for the beta.', false, '2025-09-29T14:34:12Z', '2025-09-29T14:34:12Z', 1);
UPDATE linear.linear_issues SET updated_at = '2025-09-29T14:34:12Z' WHERE id = 'ZOM-565';

INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at, sequence) VALUES ('cmt_zom543_1', 'ZOM-543', 'usr_49b9dfa5208d400d', NULL, 'Queue manager is in progress. Adding panel-order entries as each live-ops feature lands; current flow is level_end, daily_gift, season_pass, tutorial plus Collect and Win.', false, '2025-09-30T16:20:37Z', '2025-09-30T16:20:37Z', 1);
UPDATE linear.linear_issues SET updated_at = '2025-09-30T16:20:37Z' WHERE id = 'ZOM-543';

INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at, sequence) VALUES ('cmt_zom526_1', 'ZOM-526', 'usr_fc22d5941b2aeb5c', NULL, 'Token-to-live-ops travel is in progress. Season Pass tokens already fly to the icon; the Collect and Win trigger is on its branch, waiting for the merge.', false, '2025-09-24T17:30:35Z', '2025-09-24T17:30:35Z', 1);
INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at, sequence) VALUES ('cmt_zom526_2', 'ZOM-526', 'usr_fc22d5941b2aeb5c', NULL, 'Unticked this one on the master ticket, it was marked done too early. What is left is the Collect and Win trigger I mentioned above and, once that event is back, Axe Arena. It is polish on an effect that already ships for Season Pass, and the events run without it, so it does not have to land before the beta.', false, '2025-09-26T15:40:50Z', '2025-09-26T15:40:50Z', 2);
INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at, sequence) VALUES ('cmt_zom526_3', 'ZOM-526', 'usr_49b9dfa5208d400d', NULL, 'Collect and Win tokens go through the queue manager now (#472). Only the Axe Arena travel is left here, and that waits on the event coming back.', false, '2025-09-30T16:24:19Z', '2025-09-30T16:24:19Z', 3);
UPDATE linear.linear_issues SET updated_at = '2025-09-30T16:24:19Z' WHERE id = 'ZOM-526';

INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at, sequence) VALUES ('cmt_zom552_1', 'ZOM-552', 'usr_bdf01b53c6a92c5e', NULL, 'Season pass redeem events are being sent. Left and premium are in from the sheet as well; keeping this open until the data is checked against the sheet.', false, '2025-09-26T15:45:23Z', '2025-09-26T15:45:23Z', 1);
UPDATE linear.linear_issues SET updated_at = '2025-09-26T15:45:23Z' WHERE id = 'ZOM-552';

INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at, sequence) VALUES ('cmt_zom534_1', 'ZOM-534', 'usr_cd7849ec043ab3da', NULL, 'Quest points rollover now syncs quests-end with the client instead of waiting on a restart. That went out in the client builds, so nothing else has to land for the beta. I am keeping this open to watch one timing edge case on the day boundary.', false, '2025-09-25T16:35:04Z', '2025-09-25T16:35:04Z', 1);
INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at, sequence) VALUES ('cmt_zom534_2', 'ZOM-534', 'usr_63fffeb4fab5233e', NULL, 'Stayed online through the 00:00 UTC reset on the store build tonight. Quest points reset on their own, no restart. That was my report, it is good on prod now.', false, '2025-09-30T01:22:46Z', '2025-09-30T01:22:46Z', 2);
UPDATE linear.linear_issues SET updated_at = '2025-09-30T01:22:46Z' WHERE id = 'ZOM-534';

INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at, sequence) VALUES ('cmt_zom432_1', 'ZOM-432', 'usr_49b9dfa5208d400d', NULL, 'Daily gift artwork still needs the frame. Card back and gift box are done, the frame is the last piece on my side.', false, '2025-09-24T16:10:28Z', '2025-09-24T16:10:28Z', 1);
