INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at, sequence) VALUES ('cmt_zom465_2', 'ZOM-465', 'usr_c77c50cc15c5342d', NULL, 'Collect & Win came in after my note above, so its event icon is not animated yet. The Collect & Win event icon animation is still to do on my side, the other event icons are finished.', false, '2025-09-30T18:05:02Z', '2025-09-30T18:05:02Z', 2);
