INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at, sequence) VALUES ('cmt_zom471_1', 'ZOM-471', 'usr_caafeec2804b3a67', NULL, 'Not started. In the thread this came from Leonard said we do not need it, and the Plague Race icon already shows the Start button when the player is outside a race. Parking it, nothing here has to land for the beta.', false, '2025-09-17T16:45:30Z', '2025-09-17T16:45:30Z', 1);
