INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at, sequence) VALUES ('cmt_zom504_1', 'ZOM-504', 'usr_65c76e0b87aa7e9b', NULL, 'Still only shows up with the bot running; in manual play across a long endless session I could not get it. When it happens the object clears on the next throw. Visual only, no board state affected.', false, '2025-09-22T15:30:39Z', '2025-09-22T15:30:39Z', 1);
