INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at, sequence) VALUES ('cmt_zom517_1', 'ZOM-517', 'usr_Robert', NULL, 'Retested in endless mode. Enraged monsters kept their enrage through item refills, could not get one to lose it while walking.', false, '2025-09-18T17:40:54Z', '2025-09-18T17:40:54Z', 1);
