INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at, sequence) VALUES ('cmt_zom521_2', 'ZOM-521', 'usr_49b9dfa5208d400d', NULL, 'Card pack animation went in with #475. I am leaving this item, ZOM-528 and ZOM-541 open until Brian has seen it in a build.', false, '2025-09-30T16:27:38Z', '2025-09-30T16:27:38Z', 2);
